head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vMktactCd = ''; // 채권시장조치구분코드
scwin.vBndListProcsTpCd = 1; // 채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.gIsurCd = '';
scwin.vRegYn = 'N';
scwin.vRowPos = 0;
scwin.vIsuCd = '', scwin.hasAttachDoc = '';
scwin.vStdCd = '', scwin.vApplSeq = '', scwin.vNewApplSeq = '';
scwin.gBndApplId = '', scwin.gProcsStat = '0'; // 처리상태코드(0:미처리,1:접수,2:반송,3:처리완료)
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp; // 접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name search
 * @description 발행기관을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    let dsNm = 'BNS_ISUR_INFO';
    let qryId = 'lds.stf.bnscommon.select.listIsurCd';
    let param = '&{P}V_ISUR_NM=' + txb_IsurCd.getValue();
    $c.bns.fn_SearchBns('ULDSTF_N022.gfm', dts_IsurList, dsNm, qryId, param);
    let arrPnl = [pnl_IsurSearch];
    $c.bns.ShowWinArrPnl(arrPnl, grd_IsurList);
};

/**
 * @method
 * @name listSync
 * @description 발행기관별 SRI채권 종목을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    let dsNm = 'BNSSRI_APPL_LIST';
    let qryId = '';
    let param = '';
    if (scwin.vBndListProcsTpCd === 1) {
        qryId = 'lds.stf.bnslistbzappl.select.reg_cancl.appl.list';
        // param += '&{P}V_DTL_YN='+ '';
        param += '&{P}V_ISUR_CD=' + scwin.gIsurCd;
        // param += '&{P}V_ISU_CD='+ vIsuCd;

    } else {
        qryId = 'lds.stf.bnslistbzappl.select.reg_cancl.acpt.list';
        // param += '&{P}V_BND_LIST_PROCS_TP_CD='+ vBndListProcsTpCd;
        // param += '&{P}V_MKTACT_CD='+ vMktactCd;

    }
    // fn_SearchBns(vScrenID, dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd === 2) {
        $c.bns.fn_SearchBns('ULDSTF_N022.gfm', dts_List, dsNm, qryId, param);
    } else {
        $c.bns.fn_SearchBns('ULDSTF_N022.gfm', dts_List1, dsNm, qryId, param);
    }
};

/**
 * @method
 * @name dtlSync
 * @description 해당 종목의 상세내역을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.dtlSync = function() {
    let dsNm = 'BNSSRI_APPL_LIST';
    let qryId = '';
    let param = '';
    const fileDsNm = 'BNSSRI_APPL_FILE_LIST';
    let fileQryId = '';
    let fileParam = '';

    // SRI채권정보
    if (scwin.vBndListProcsTpCd === 1) {
        qryId = 'lds.stf.bnslistbzappl.select.reg_cancl.appl.dtl';
        param += '&{P}V_ISUR_CD=' + scwin.gIsurCd;
        param += '&{P}V_STD_CD=' + scwin.vStdCd;
        // param += '&{P}V_APPL_ISU_SEQ='+ vApplSeq;

    } else {
        qryId = 'lds.stf.bnslistbzappl.select.reg_cancl.acpt.dtl';
        param += '&{P}V_ISUR_CD=' + scwin.gIsurCd;
        param += '&{P}V_STD_CD=' + scwin.vStdCd;
        param += '&{P}V_APPL_ISU_SEQ=' + scwin.vApplSeq;
    }
    $c.bns.fn_SearchBns('ULDSTF_N022.gfm', dts_DtlInfo, dsNm, qryId, param);

    // 파일정보
    if (scwin.vBndListProcsTpCd === 2) {
        fileQryId = 'lds.stf.bnssri.select.sriBndMgtFileList';
        fileParam += '&{P}V_STD_CD=' + scwin.vStdCd;
        fileParam += '&{P}V_APPL_ISU_SEQ=' + scwin.vApplSeq;
        $c.bns.fn_SearchBns('ULDSTF_N022.gfm', dts_fileList, fileDsNm, fileQryId, fileParam);
    }
};

/**
 * @method
 * @name seqSearch
 * @description 채권신청번호 생성
 * @returns {void}
 * @hidden N
 */
scwin.seqSearch = function() {
    let dsNm = 'BNS_SRI_APPL_ISU_SEQ_NEXTVAL';
    let qryId = 'lds.stf.bnscommon.select.APPL_ISU_SEQ_NextVal';
    let param = '&{P}V_STD_CD=' + scwin.vStdCd;
    dts_NextSeq.SyncLoad = 'true';
    $c.bns.fn_SearchBns('ULDSTF_N022.gfm', dts_NextSeq, dsNm, qryId, param);
};

/**
 * @method
 * @name inputCheck
 * @description 필수 입력 값을 체크한다.
 * @param {*} GUBUN GUBUN
 * @returns {void}
 * @hidden N
 */
scwin.inputCheck = function(GUBUN) {
    if (GUBUN === 'Acpt') {
        if (edt_REG_CANCL_DD.getValue() === '') {
            alert("[취소일]을 입력하십시오.");

            edt_REG_CANCL_DD.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_REG_CANCL_DD, "취소일")) {
            return false;
        }
        if (cmb_BndTpCd.getValue() === '') {
            alert("[등록취소사유]를 입력하십시오.");

            cmb_BndTpCd.focus();
            return false;
        }
        // if (! checkMaxLength(txb_DlstRsn, 60, '폐지사유') ) return false;

        if (txb_REG_CANCL_REL_GRND.getValue() === '') {
            alert("[관련근거]를 입력하십시오.");

            txb_REG_CANCL_REL_GRND.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_REG_CANCL_REL_GRND, 200, '관련근거')) return false;
    } else {
        if (edt_REG_CANCL_DD2.getValue() === '') {
            alert("[취소일]을 입력하십시오.");

            edt_REG_CANCL_DD2.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_REG_CANCL_DD2, "취소일")) {
            return false;
        }
        if (cmb_BndTpCd2.getValue() === '') {
            alert("[등록취소사유]를 입력하십시오.");

            cmb_BndTpCd2.focus();
            return false;
        }
        if (txb_REG_CANCL_REL_GRND2.getValue() === '') {
            alert("[관련근거]를 입력하십시오.");

            txb_REG_CANCL_REL_GRND2.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_REG_CANCL_REL_GRND2, 200, '관련근거')) return false;
    }
    return true;
};

/**
 * @method
 * @name acptProcsCheck
 * @description 접수, 처리완료시 공통 체크 구문
 * @param {*} gubun gubun
 * @returns {void}
 * @hidden N
 */
scwin.acptProcsCheck = function(gubun) {
    if (gubun === 'Acpt') {
        // 필수입력값 체크
        if (scwin.inputCheck('Acpt') === false) return 1;

        // 적용일,매매일,마감일,채권마감 체크
        if ($c.bns.fn_CheckCmDataSriRegCancl('ULDSTF_N022.gfm', dts_CheckCmData, edt_REG_CANCL_DD.getValue()) > 0) return 1;
    } else if (gubun === 'Procs') {
        // 필수입력값 체크
        if (scwin.inputCheck('Proc') === false) return 1;

        // 적용일,매매일,마감일,채권마감 체크
        if ($c.bns.fn_CheckCmDataSriRegCancl('ULDSTF_N022.gfm', dts_CheckCmData, edt_REG_CANCL_DD2.getValue()) > 0) return 1;
    }

    scwin.vIsuCd = dts_DtlInfo.NameValue(1, "ISU_CD");

    scwin.hasAttachDoc = dts_DtlInfo.NameValue(1, "HAS_ATTACH_DOC");

    // 변경된 데이터가 없더라도 데이터셋 전송
    dts_DtlInfo.UseChangeInfo = "False";
    return 0;
};

/**
 * @method
 * @name acpt
 * @description 신청데이터를 접수 처리한다.
 * @returns {void}
 * @hidden N
 */
scwin.acpt = function() {
    // 채권신청ID생성 체크
    // if (gBndApplId == '') {
    //    alert("채권신청ID를 생성하지 못했습니다.");
    //    return;
    // }

    // 접수, 처리완료 공통 체크
    if (scwin.acptProcsCheck('Acpt') > 0) return;

    // 접수처리건/미처리건 확인
    let dsNm = 'BNS_COM_CD';
    let qryId = 'lds.stf.bnslistbzappl.select.reg_cancl.uncompleted';

    let param = "&{P}V_STD_CD=" + dts_DtlInfo.NameValue(1, "STD_CD");
    dts_Temp.SyncLoad = true;
    $c.bns.fn_SearchBns('ULDSTF_N022.gfm', dts_Temp, dsNm, qryId, param);

    if (dts_Temp.NameValue(1, 'VALUE') > 0) {
        alert('등록취소 접수내역에 해당 종목이 존재합니다. \n\n[접수내역]을 확인하여 주십시요.');
        return;
    }

    // 접수
    if (!confirm("접수처리 하시겠습니까?")) return;
    let url = "/bns/IsuChgEtc.do?method=processApplAcptSriRegCancl";
    url += "&SCREN_ID=" + 'ULDSTF_N022.gfm';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&FILE_FAX=" + "ESG";
    trs_Save.Action = $c.lce.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo,I:pFile=dts_fileList)";

    trs_Save.Post();
};

/**
 * @method
 * @name procsComplt
 * @description 처리완료 및 수정을 처리한다.
 * @returns {void}
 * @hidden N
 */
scwin.procsComplt = function() {
    // 접수, 처리완료 공통 체크
    if (scwin.acptProcsCheck('Procs') > 0) return;
    let url;
    if (scwin.processGp === '4') {
        // 접수 후 수정 및 반송시 체크한다.
        // if (fn_CheckModAndRet(vScrenID, dts_CheckCmData, gBndApplId) > 0) return;
        if (!confirm("수정처리 하시겠습니까?")) return;
        if (scwin.gProcsStat !== "3") {
            url = "/bns/IsuChgEtc.do?method=processUpdateSriRegCancl";
        }
    } else {
        // if(! fn_EndConfirm(hasAttachDoc, '처리완료')) return;
        if (!confirm("처리완료 하시겠습니까?")) return;
        if (scwin.gProcsStat !== "3") {
            url = "/bns/IsuChgEtc.do?method=processCompltSriRegCancl";
        }
    }

    // alert(gProcsStat);

    url += "&PROCS_STAT_CD=" + scwin.gProcsStat;
    url += "&SCREN_ID=" + 'ULDSTF_N022.gfm';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;

    // alert(url);

    trs_Save.Action = $c.lce.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo,I:pFile=dts_fileList)";

    trs_Save.Post();
};

/**
 * @method
 * @name getCommonKey
 * @description 팝업에 넘길 키데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getCommonKey = function(arrPar) {
    arrPar[0] = {
        // 첨부문서 목록 팝업

        BND_APPL_ID: dts_DtlInfo.NameValue(1, "BND_APPL_ID"),

        BND_LIST_PROCS_TP_CD: dts_DtlInfo.NameValue(1, "BND_LIST_PROCS_TP_CD"),

        ISU_CD: dts_DtlInfo.NameValue(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name getReturn
 * @description 반송 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getReturn = function(arrPar) {
    arrPar[0] = {

        STD_CD: dts_DtlInfo.NameValue(1, "STD_CD"),

        APPL_ISU_SEQ: dts_DtlInfo.NameValue(1, "APPL_ISU_SEQ"),

        ISUR_NM: dts_DtlInfo.NameValue(1, "ISUR_NM"),

        ISU_NM: dts_DtlInfo.NameValue(1, "ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setReturn
 * @description 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setReturn = function(arrPar) {
    if ("Y" === arrPar[0].SUCCESS_YN) {
        scwin.listSync();
    }
};

/**
 * @method
 * @name getParIsuDelInfo
 * @description 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuDelInfo = function(arrPar) {
    arrPar[0] = {

        STD_CD: dts_DtlInfo.NameValue(1, "STD_CD"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name getParApprovFileWrt
 * @description 결재파일생성 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParApprovFileWrt = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.gBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        BND_MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name getParDelistRsn
 * @description 상장페지 사유선택 (종목)  팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParDelistRsn = function(arrPar) {
    arrPar[0] = {

        BND_DELIST_CD: dts_DtlInfo.NameValue(1, "BND_DELIST_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParDelistRsn
 * @description 상장페지 사유선택 (종목)  팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParDelistRsn = function(arrPar) {
    const getData = arrPar[0].BND_DELIST_CD + " " + arrPar[0].DELIST_RSN_DTL;
    if (scwin.vBndListProcsTpCd === 1) {
        txb_DlstRsn.setValue(getData);
        txb_MemoContn.setValue(arrPar[0].MEMO);
    } else {
        txb_DlstRsn2.setValue(getData);
        txb_MemoContn2.setValue(arrPar[0].MEMO);
    }
};

/**
 * @method
 * @name anfeeRefnd
 * @description 연부과금 환급수수료 등록 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.anfeeRefnd = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.gBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        MKTACT_TP_CD: scwin.vMktactCd,
        SCREN_ID: 'ULDSTF_N022.gfm'
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setAnfeeRefnd
 * @description 연부과금 환급수수료 등록 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setAnfeeRefnd = function(arrPar) {
    scwin.vRegYn = arrPar[0].REG_YN;
    if (scwin.vRegYn === 'Y') {
        scwin.vRowPos = dts_List.RowPosition;
        scwin.listSync();
    }
};

/**
 * @method
 * @name procBtnStat
 * @description 처리 상태가 처리완료일 경우, 처리완료 버튼 비활성화
 * @returns {void}
 * @hidden N
 */
scwin.procBtnStat = function() {
    if (scwin.gProcsStat === "1") {
        btn_Proc.src = "../img/bns/btn_20.gif";
        btn_Proc.setDisabled(true);
        btn_Mod.src = "../img/bns/btn_modify_n.gif";
        btn_Mod.setDisabled(true);
        //            btn_TeamleadrConfrm.src = "../img/bns/btn_21_d.gif";
        //            btn_TeamleadrConfrm.disabled = true;
        btn_Ret2.src = "../img/bns/btn_Ret_n.gif";
        btn_Ret2.setDisabled(true);
    } else if (scwin.gProcsStat === "3") {
        btn_Proc.src = "../img/bns/btn_20_d.gif";
        btn_Proc.setDisabled(false);
        btn_Mod.src = "../img/bns/btn_modify_nd.gif";
        btn_Mod.setDisabled(false);
        //            btn_TeamleadrConfrm.src = "../img/bns/btn_21.gif";
        //            btn_TeamleadrConfrm.disabled = false;
        btn_Ret2.src = "../img/bns/btn_Ret_nd.gif";
        btn_Ret2.setDisabled(false);
    }
};

/*******************************************************************
 * 함수명   : fn_PopReturn
 * 설명     : 반송처리 팝업을 보여준다.
 * argument : object
 *******************************************************************/
$c.bns.fn_PopReturn = function(grdObj) {
    $c.lce.fn_SetPopupPos(grdObj, 'E');

    const options = {
        id: "ULDBNS21901",
        title: "반송처리",
        type: "browserPopup",
        width: "480px",
        height: "280px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/bnslistbzappl/ULDBNS21901.gfm", options);
};

/**
 * @method
 * @name ins_return
 * @description 반송후 로직
 * @param {*} vRsn vRsn
 * @returns {void}
 * @hidden N
 */
scwin.ins_return = function(vRsn) {
    let url = "/bns/IsuChgEtc.do?method=updateSriBndReturnBtn";
