/**
 * @method
 * @name selectAttach
 * @description 파일 추가
 * @returns {void}
 * @hidden N
 */
scwin.selectAttach = function() {
    // if (fn_InputCheck('Select') == false) return;
    if (dts_fileList.CountRow === 1) {
        alert("더이상 추가하실 수 없습니다.");
        return;
    }
    file.Value = "";

    file.open();
    if (file.Value !== "") {
        const vFile = file.Value;
        let vFileNm = vFile.split("\\");
        vFileNm = vFileNm[vFileNm.length - 1];
        if (vFileNm !== "") {
            if (scwin.checkExtension(vFileNm)) return; // 파일 확장자 체크

            dts_fileList.AddRow();
        } else {
            return;

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

        } /*ORG SRC: dts_fileList.NameString(dts_fileList.RowPosition, "ISUR_CD") = gIsurCd;*/ X = scwin.gIsurCd; /*ORG SRC: dts_fileList.NameString(dts_fileList.RowPosition, "FILE_NM") = vFileNm;*/ X = vFileNm; /*ORG SRC: dts_fileList.NameString(dts_fileList.RowPosition, "FILE_URL") = file.Value;*/ X = file.Value; /*ORG SRC: dts_fileList.NameString(dts_fileList.RowPosition, "FILE_TP_CD") = '12'; //등록취소신청서*/ X = '12'; // 등록취소신청서

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        /*ORG SRC: dts_fileList.NameString(dts_fileList.RowPosition, "STD_CD") = vStdCd;*/
        X = scwin.vStdCd;
        // dts_fileList.NameString(dts_fileList.RowPosition, "APPL_ISU_SEQ")  = vNewApplSeq;//새로운 신청번호는 접수버튼 누를때 생성해서 넣어줘야함

    }
};

/**
 * @method
 * @name checkExtension
 * @description 업로드 파일 확장자 체크
 * @param {String} fileNm fileNm
 * @returns {void}
 * @hidden N
 */
scwin.checkExtension = function(fileNm) {
    // var fileExts = new Array(".hwp",".docx",".doc",".xls",".xlsx",".ppt",".pptx",".pdf",".gif",".jpg",".jpeg",".bmp",".tif",".txt",".drt",".dsd",".png");// 허가 확장자 목록
    const fileExts = new Array(".pdf"); // 허가 확장자 목록
    const vsFileNm = fileNm;
    const vsFileExts = vsFileNm.substr(vsFileNm.lastIndexOf("."), vsFileNm.length);
    let vsFlag = true;
    for (let i = 0; i < fileExts.length; i++) {
        if (fileExts[i] === vsFileExts) {
            vsFlag = false;
            break;
        }
    }
    if (vsFlag) {
        alert("업로드할 수 없는 확장자입니다. 확인바랍니다.");
        return true;
    }
    return false;
};

/**
 * @method
 * @name fileDownload
 * @description 파일 다운로드
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.fileDownload = function(row) {

    if (dts_fileList.NameValue(row, "ORGN_FILE_NM") === "") {
        return;
    } else {
        let url = "/bns/BnsAttachDocFileDownload.do";
        url += "?ATTACH_FILE_TP_CD=" + 2;

        url += "&ISUR_CD=" + dts_fileList.NameValue(row, "ISUR_CD");

        url += "&APPL_DD=" + dts_fileList.NameValue(row, "APPL_DD");

        url += "&APPL_TM=" + dts_fileList.NameValue(row, "APPL_TM");
        location.href = url;
    }
};

