/**
 * @method
 * @name setCheckBoxALL
 * @description 그리드 체크박스 전체선택 또는 전체선택 해제
 * @param {*} grdObj grdObj
 * @param {*} dtsObj dtsObj
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.setCheckBoxALL = function(grdObj, dtsObj, bCheck) {
    let vcd = "";
    if (bCheck === '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.Redraw = false;
    for (let i = 1; i <= dtsObj.CountRow; i++) {
        // if (dtsObj.NameString(i, "PROCS_STAT") != '처리완료') { //처리완료만 팀장확인 대상임

        if (dtsObj.NameString(i, "STAT") !== '처리완료' || (dtsObj.NameString(i, "TEAMLEADER_CONFRM_DD") !== "undefined" && dtsObj.NameString(i, "TEAMLEADER_CONFRM_DD") !== '-' && dtsObj.NameString(i, "TEAMLEADER_CONFRM_DD") !== '')) {
            // 처리완료만 팀장확인 대상임

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            /*ORG SRC: dtsObj.NameString(i, "CHK") = "F";*/
            X = "F";
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            /*ORG SRC: dtsObj.NameString(i, "CHK") = vcd;*/
            X = vcd;
        }
    }
    grdObj.Redraw = true;
};

