    dts_fileList.SetDataHeader("ISUR_CD:String, FILE_NM:String, FILE_URL:Url, FILE_TP_CD:String,SUPLY_FND_USE_RPT_YY:String, FILE_COMMENT:String, STD_CD:String, APPL_ISU_SEQ:String");
};

