    if (scwin.vDtlInfoRowCount === 0) return;
    // 접수 후 수정 및 반송시 체크한다.
    if ($c.bns.fn_CheckModAndRet('ULDSTF_N022.gfm', dts_CheckCmData, scwin.gBndApplId) > 0) return;
    scwin.processGp = '2';
    scwin.fn_GetPar = scwin.getReturn;
    scwin.fn_SetPar = scwin.setReturn;
    scwin.fn_PopReturn(grd_List2);
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp === '1') {
        alert($c.stf.getMessageParam("MSG-A002", "접수"));
    }
    if (scwin.processGp === '3') {
        alert($c.stf.getMessageParam("MSG-A002", "처리완료"));
    }
    if (scwin.processGp === '4') {
        alert($c.stf.getMessageParam("MSG-A002", "수정"));
    }
    if (scwin.processGp === '6') {
        alert($c.stf.getMessageParam("MSG-A002", "팀장확인"));
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp === '1') {
        alert($c.stf.getMessageParam("MSG-A001", "접수"));

        dts_DtlInfo.ClearData();

        dts_fileList.ClearData();
    }
    if (scwin.processGp === '3') {
        alert($c.stf.getMessageParam("MSG-0001"));
        scwin.listSync();
    }
    if (scwin.processGp === '4') {
        alert($c.stf.getMessageParam("MSG-A001", "수정"));
        scwin.listSync();
    }
    if (scwin.processGp === '6') {
        alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
        scwin.listSync();
    }
    scwin.vRegYn = 'N';
};

